From d8003f5c06accf5cc34102c791ae069287529816 Mon Sep 17 00:00:00 2001
From: Arne Hassel <arne.hassel@gmail.com>
Date: Wed, 24 Oct 2018 08:13:28 +0200
Subject: [PATCH 01/21] Adding options to handle T&C

---
 bin/lib/options.js | 15 +++++++++++++++
 1 file changed, 15 insertions(+)

diff --git a/bin/lib/options.js b/bin/lib/options.js
index 4efbf07d2..245225cba 100644
--- a/bin/lib/options.js
+++ b/bin/lib/options.js
@@ -334,6 +334,21 @@ module.exports = [
     name: 'server-logo',
     help: 'A logo that represents you, your brand, or your server (not required)',
     prompt: true
+  },
+  {
+    name: 'enforceToc',
+    help: 'Do you want to enforce Terms & Conditions for your service?',
+    flag: true,
+    prompt: true,
+    default: true,
+    when: answers => answers.multiuser
+  },
+  {
+    name: 'tocUri',
+    help: 'URI to your Terms & Conditions',
+    prompt: true,
+    validate: validUri,
+    when: answers => answers.enforceToc
   }
 ]


From b02bf0d157fc9c81c1957ec404dd6189dc2cb878 Mon Sep 17 00:00:00 2001
From: Arne Hassel <arne.hassel@gmail.com>
Date: Wed, 24 Oct 2018 09:13:11 +0200
Subject: [PATCH 02/21] Added checkbox to register-form

Also added handlebar-helpers
---
 default-views/account/register-form.hbs |  9 +++++++++
 lib/create-app.js                       |  4 +++-
 lib/requests/auth-request.js            |  4 ++++
 lib/requests/create-account-request.js  | 21 ++++++++++++++-------
 package.json                            |  1 +
 5 files changed, 31 insertions(+), 8 deletions(-)

diff --git a/default-views/account/register-form.hbs b/default-views/account/register-form.hbs
index 12166f888..93e7d98a1 100644
--- a/default-views/account/register-form.hbs
+++ b/default-views/account/register-form.hbs
@@ -71,6 +71,15 @@
             </span>
           </div>

+          {{#if (and enforceToc tocUri)}}
+            <div class="checkbox">
+              <label>
+                <input type="checkbox" name="acceptToc">
+                I agree to the <a href="{{tocUri}}" target="_blank">Terms & Conditions</a> of this service
+              </label>
+            </div>
+          {{/if}}
+

           <button type="submit" class="btn btn-primary" id="register">Register</button>

